/**
 * Minimal centered layout shared by every auth-* route: no nav, no
 * sidebar, just the page content inside the `main` landmark, behind a
 * skip link that is visible only when focused. Each auth-* page
 * composes its own `AuthCard` inside this shell.
 */

import { getTranslations } from "next-intl/server";
import type { ReactNode } from "react";

const SKIP_LINK_CLASS =
  "sr-only focus:not-sr-only focus:fixed focus:top-3 focus:left-3 focus:z-50 focus:rounded-lg focus:border focus:border-ring focus:bg-background focus:px-3 focus:py-2 focus:text-sm focus:font-medium focus:text-foreground focus:shadow-md focus:outline-none focus:ring-3 focus:ring-ring/40";

export default async function AuthLayout({
  children,
}: {
  children: ReactNode;
}) {
  const t = await getTranslations("auth-login");
  return (
    <>
      <a href="#main-content" className={SKIP_LINK_CLASS}>
        {t("skipToContent")}
      </a>
      <main
        id="main-content"
        tabIndex={-1}
        className="min-h-screen bg-background outline-none"
      >
        {children}
      </main>
    </>
  );
}

import type { Metadata } from "next";
import { getLocale, getTranslations } from "next-intl/server";

import { getAuthSession } from "@intelligo-dev/auth";

import { redirect } from "@/i18n/navigation";
import { returnPath } from "@/lib/auth-validation";
import { AuthCard } from "@/components/auth/auth-card";
import { SocialLoginButtons } from "@/components/auth/social-login-buttons";
import { LoginForm } from "@/components/auth/login-form";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("auth-login");
  return {
    title: t("metadata.title"),
    description: t("metadata.description"),
  };
}

/**
 * A signed-in visitor has no use for this page.
 *
 * Done here rather than in middleware because middleware only sees the
 * session cookie, not the session. Redirecting on the cookie while the
 * authenticated app layout redirects on the real session is an infinite
 * loop for anyone holding a stale one — revoked elsewhere, expired row,
 * rotated secret — and the loop locks them out of the page that would
 * fix it.
 */
async function redirectIfSignedIn(next: string): Promise<void> {
  if (await getAuthSession())
    redirect({ href: next, locale: await getLocale() });
}

export default async function LoginPage({
  searchParams,
}: {
  searchParams: Promise<{ next?: string | string[] }>;
}) {
  // Where the reader was going — an invitation link, say — when they
  // were sent here to sign in.
  const raw = (await searchParams).next;
  const next = returnPath(Array.isArray(raw) ? raw[0] : raw);
  await redirectIfSignedIn(next);

  const t = await getTranslations("auth-login");

  // OAuth provider buttons only render for providers actually configured
  // on the server — checked here, not in the client component, so an
  // unconfigured client id/secret never reaches the browser at all.
  const providers: string[] = [];
  if (process.env.GOOGLE_CLIENT_ID && process.env.GOOGLE_CLIENT_SECRET) {
    providers.push("google");
  }
  if (process.env.GITHUB_CLIENT_ID && process.env.GITHUB_CLIENT_SECRET) {
    providers.push("github");
  }

  return (
    <AuthCard title={t("card.title")} description={t("card.description")}>
      <div className="space-y-6">
        <SocialLoginButtons providers={providers} next={next} />
        <LoginForm next={next} />
      </div>
    </AuthCard>
  );
}

/**
 * Shared auth page shell, unbranded.
 *
 * Ships with `auth-login`; `auth-signup`, `auth-password-reset`, and
 * `auth-email-verification` all import it from `@/components/auth/auth-card`
 * once installed (see those items' descriptions for the cross-item
 * dependency). A consumer that wants a logo or product name above the
 * card composes it around this component (or in `app/(auth)/layout.tsx`)
 * rather than editing this file — keeping it unbranded is what lets every
 * auth-* item reuse it as-is.
 */

import type { ReactNode } from "react";

interface AuthCardProps {
  title: string;
  description?: string;
  children: ReactNode;
  footer?: ReactNode;
}

export function AuthCard({
  title,
  description,
  children,
  footer,
}: AuthCardProps) {
  return (
    <div className="flex min-h-screen flex-col items-center justify-center px-4 py-12">
      <div className="w-full max-w-md">
        <div className="rounded-xl border border-border bg-card p-8 shadow-sm">
          <div className="mb-6 text-center">
            <h1 className="text-2xl font-bold text-foreground">{title}</h1>
            {description && (
              <p className="mt-1 text-sm text-muted-foreground">
                {description}
              </p>
            )}
          </div>
          {children}
          {footer && <div className="mt-6">{footer}</div>}
        </div>
      </div>
    </div>
  );
}

"use client";

/**
 * Email + password login form. Calls the Better-Auth client SDK
 * (`@intelligo-dev/auth/client`) directly — no raw `fetch("/api/auth/*")`.
 */

import { useState } from "react";
import { useTranslations } from "next-intl";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";

import { authClient } from "@intelligo-dev/auth/client";

import { Link, useRouter } from "@/i18n/navigation";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Field, FieldError, FieldLabel } from "@/components/ui/field";
import { Spinner } from "@/components/ui/spinner";
import { loginSchema, type LoginInput } from "@/lib/auth-validation";

/** `next`: where to go once signed in — a path on this site. */
export function LoginForm({ next = "/dashboard" }: { next?: string }) {
  const t = useTranslations("auth-login");
  const router = useRouter();
  const [formError, setFormError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<LoginInput>({
    resolver: zodResolver(loginSchema),
  });

  async function onSubmit(data: LoginInput) {
    try {
      setFormError(null);
      setIsLoading(true);

      const result = await authClient.signIn.email({
        email: data.email,
        password: data.password,
        callbackURL: next,
      });

      if (result.error) {
        setFormError(
          result.error.message ?? t("loginForm.errors.invalidCredentials")
        );
        setIsLoading(false);
        return;
      }

      router.push(next);
    } catch (error) {
      console.error("Login error:", error);
      setFormError(t("loginForm.errors.unexpected"));
      setIsLoading(false);
    }
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} noValidate className="space-y-4">
      {formError && (
        <Alert variant="destructive">
          <AlertDescription>{formError}</AlertDescription>
        </Alert>
      )}

      <Field data-invalid={errors.email ? true : undefined}>
        <FieldLabel htmlFor="email">{t("loginForm.emailLabel")}</FieldLabel>
        <Input
          id="email"
          type="email"
          autoComplete="email"
          disabled={isLoading}
          aria-invalid={errors.email ? true : undefined}
          aria-describedby={errors.email ? "email-error" : undefined}
          {...register("email")}
        />
        {errors.email && (
          <FieldError id="email-error">
            {t(`validation.${errors.email.message}`)}
          </FieldError>
        )}
      </Field>

      <Field data-invalid={errors.password ? true : undefined}>
        <div className="flex items-center justify-between">
          <FieldLabel htmlFor="password">
            {t("loginForm.passwordLabel")}
          </FieldLabel>
          <Link
            href="/forgot-password"
            className="text-xs font-medium text-primary hover:text-primary/80"
          >
            {t("loginForm.forgotPassword")}
          </Link>
        </div>
        <Input
          id="password"
          type="password"
          autoComplete="current-password"
          disabled={isLoading}
          aria-invalid={errors.password ? true : undefined}
          aria-describedby={errors.password ? "password-error" : undefined}
          {...register("password")}
        />
        {errors.password && (
          <FieldError id="password-error">
            {t(`validation.${errors.password.message}`)}
          </FieldError>
        )}
      </Field>

      <Button
        type="submit"
        className="w-full"
        disabled={isLoading}
        aria-busy={isLoading || undefined}
      >
        {isLoading ? (
          <>
            <Spinner data-icon="inline-start" />
            {t("loginForm.submitting")}
          </>
        ) : (
          t("loginForm.submit")
        )}
      </Button>

      <p className="text-center text-sm text-muted-foreground">
        {t("loginForm.noAccount")}{" "}
        <Link
          href={
            next === "/dashboard"
              ? "/signup"
              : `/signup?next=${encodeURIComponent(next)}`
          }
          className="font-medium text-primary hover:text-primary/80"
        >
          {t("loginForm.signUpLink")}
        </Link>
      </p>
    </form>
  );
}

"use client";

/**
 * OAuth provider buttons — renders only the providers the server page
 * passes in via `providers` (see `page.tsx`: the env-var check is
 * server-side, so a provider with no client id/secret configured never
 * reaches the client at all). Calls the Better-Auth client SDK directly;
 * no raw `fetch("/api/auth/*")`.
 *
 * Ships with `auth-login`; `auth-signup` reuses this same file from
 * `@/components/auth/social-login-buttons` once installed, so its copy
 * text lives under the `auth-login` message namespace regardless of
 * which page renders it — see that item's description for the
 * cross-item dependency.
 */

import { useState } from "react";
import { useTranslations } from "next-intl";

import { authClient } from "@intelligo-dev/auth/client";

import { Button } from "@/components/ui/button";
import { Spinner } from "@/components/ui/spinner";

type Provider = "google" | "github";

interface SocialLoginButtonsProps {
  providers: string[];
  /** Where to go once signed in — a path on this site. */
  next?: string;
}

export function SocialLoginButtons({
  providers,
  next = "/dashboard",
}: SocialLoginButtonsProps) {
  const t = useTranslations("auth-login");
  const [loadingProvider, setLoadingProvider] = useState<Provider | null>(null);
  const [failed, setFailed] = useState(false);

  if (providers.length === 0) {
    return null;
  }

  async function handleSocialLogin(provider: Provider) {
    setFailed(false);
    setLoadingProvider(provider);
    try {
      // On success the browser leaves for the provider. A provider the
      // server does not have configured answers `{ error }` instead of
      // throwing, and the buttons must come back either way.
      const { error } = await authClient.signIn.social({
        provider,
        callbackURL: next,
      });
      if (!error) return;
    } catch {
      // Same outcome as `{ error }`: stay on the page and say so.
    }
    setFailed(true);
    setLoadingProvider(null);
  }

  return (
    <div className="space-y-4">
      {failed ? (
        <p role="alert" className="text-sm text-destructive">
          {t("socialLogin.failed")}
        </p>
      ) : null}
      <div className="grid gap-2">
        {providers.includes("google") && (
          <Button
            type="button"
            variant="outline"
            onClick={() => handleSocialLogin("google")}
            disabled={loadingProvider !== null}
            className="w-full"
          >
            {loadingProvider === "google" ? (
              <Spinner />
            ) : (
              <svg
                width="16"
                height="16"
                viewBox="0 0 18 18"
                fill="none"
                aria-hidden="true"
              >
                <path
                  d="M17.64 9.2c0-.637-.057-1.251-.164-1.84H9v3.481h4.844a4.14 4.14 0 0 1-1.796 2.716v2.259h2.908c1.702-1.567 2.684-3.875 2.684-6.615Z"
                  fill="#4285F4"
                />
                <path
                  d="M9 18c2.43 0 4.467-.806 5.956-2.18l-2.908-2.259c-.806.54-1.837.86-3.048.86-2.344 0-4.328-1.584-5.036-3.711H.957v2.332A8.997 8.997 0 0 0 9 18Z"
                  fill="#34A853"
                />
                <path
                  d="M3.964 10.71A5.41 5.41 0 0 1 3.682 9c0-.593.102-1.17.282-1.71V4.958H.957A8.997 8.997 0 0 0 0 9c0 1.452.348 2.827.957 4.042l3.007-2.332Z"
                  fill="#FBBC05"
                />
                <path
                  d="M9 3.58c1.321 0 2.508.454 3.44 1.345l2.582-2.58C13.463.891 11.426 0 9 0A8.997 8.997 0 0 0 .957 4.958L3.964 6.29C4.672 4.163 6.656 3.58 9 3.58Z"
                  fill="#EA4335"
                />
              </svg>
            )}
            {loadingProvider === "google"
              ? t("socialLogin.connecting")
              : t("socialLogin.continueWithGoogle")}
          </Button>
        )}

        {providers.includes("github") && (
          <Button
            type="button"
            variant="outline"
            onClick={() => handleSocialLogin("github")}
            disabled={loadingProvider !== null}
            className="w-full"
          >
            {loadingProvider === "github" ? (
              <Spinner />
            ) : (
              <svg
                className="size-4"
                fill="currentColor"
                viewBox="0 0 24 24"
                aria-hidden="true"
              >
                <path d="M12 0c-6.626 0-12 5.373-12 12 0 5.302 3.438 9.8 8.207 11.387.599.111.793-.261.793-.577v-2.234c-3.338.726-4.033-1.416-4.033-1.416-.546-1.387-1.333-1.756-1.333-1.756-1.089-.745.083-.729.083-.729 1.205.084 1.839 1.237 1.839 1.237 1.07 1.834 2.807 1.304 3.492.997.107-.775.418-1.305.762-1.604-2.665-.305-5.467-1.334-5.467-5.931 0-1.311.469-2.381 1.236-3.221-.124-.303-.535-1.524.117-3.176 0 0 1.008-.322 3.301 1.23.957-.266 1.983-.399 3.003-.404 1.02.005 2.047.138 3.006.404 2.291-1.552 3.297-1.23 3.297-1.23.653 1.653.242 2.874.118 3.176.77.84 1.235 1.911 1.235 3.221 0 4.609-2.807 5.624-5.479 5.921.43.372.823 1.102.823 2.222v3.293c0 .319.192.694.801.576 4.765-1.589 8.199-6.086 8.199-11.386 0-6.627-5.373-12-12-12z" />
              </svg>
            )}
            {loadingProvider === "github"
              ? t("socialLogin.connecting")
              : t("socialLogin.continueWithGithub")}
          </Button>
        )}
      </div>

      <div className="flex items-center gap-4">
        <div className="h-px flex-1 bg-border" />
        <span className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
          {t("socialLogin.orContinueWith")}
        </span>
        <div className="h-px flex-1 bg-border" />
      </div>
    </div>
  );
}

/**
 * Shared client-side validation schemas for the auth-* registry items.
 *
 * Ships with `auth-login`; `auth-signup` and `auth-password-reset` import
 * it from `@/lib/auth-validation` once installed (see those items'
 * descriptions for the cross-item dependency). Plain zod, no
 * `@intelligo-dev/*` imports.
 *
 * Validation copy is user-facing, so these schemas do not carry literal
 * English strings — they carry stable error CODES (plain identifiers, not
 * translated text), and the form component that owns each schema maps a
 * code to `t(\`validation.${code}\`)` under its own registry item's
 * message namespace. A schema file has no component tree to
 * call `useTranslations`/`getTranslations` from, so translation happens
 * one layer up, in the form.
 */

import { z } from "zod";

/** At least one uppercase letter, one lowercase letter, and one digit. */
const passwordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).+$/;

export const loginSchema = z.object({
  email: z.string().email("emailInvalid"),
  password: z.string().min(8, "passwordTooShort"),
});

export type LoginInput = z.infer<typeof loginSchema>;

export const signupSchema = z
  .object({
    name: z.string().min(2, "nameTooShort").max(50, "nameTooLong"),
    email: z.string().email("emailInvalid"),
    password: z
      .string()
      .min(8, "passwordTooShort")
      .max(128, "passwordTooLong")
      .regex(passwordRegex, "passwordWeak"),
    confirmPassword: z.string(),
  })
  .refine((data) => data.password === data.confirmPassword, {
    message: "passwordMismatch",
    path: ["confirmPassword"],
  });

export type SignupInput = z.infer<typeof signupSchema>;

export const forgotPasswordSchema = z.object({
  email: z.string().email("emailInvalid"),
});

export type ForgotPasswordInput = z.infer<typeof forgotPasswordSchema>;

export const resetPasswordSchema = z
  .object({
    password: z
      .string()
      .min(8, "passwordTooShort")
      .max(128, "passwordTooLong")
      .regex(passwordRegex, "passwordWeak"),
    confirmPassword: z.string(),
  })
  .refine((data) => data.password === data.confirmPassword, {
    message: "passwordMismatch",
    path: ["confirmPassword"],
  });

export type ResetPasswordInput = z.infer<typeof resetPasswordSchema>;

/**
 * Where to go after signing in: `next` when it is a path on this site,
 * `/dashboard` otherwise. A full URL, or `//host`, would let a link send
 * a reader who just signed in to somebody else's site.
 */
export function returnPath(next: string | null | undefined): string {
  return typeof next === "string" && /^\/(?![/\\])/.test(next)
    ? next
    : "/dashboard";
}

{
  "skipToContent": "Skip to content",
  "metadata": {
    "title": "Log in",
    "description": "Log in to your account."
  },
  "card": {
    "title": "Welcome back",
    "description": "Log in to your account"
  },
  "loginForm": {
    "emailLabel": "Email",
    "passwordLabel": "Password",
    "forgotPassword": "Forgot password?",
    "submit": "Sign in",
    "submitting": "Signing in…",
    "noAccount": "Don't have an account?",
    "signUpLink": "Sign up",
    "errors": {
      "invalidCredentials": "Incorrect email or password.",
      "unexpected": "Something went wrong. Please try again."
    }
  },
  "socialLogin": {
    "connecting": "Connecting…",
    "continueWithGoogle": "Continue with Google",
    "continueWithGithub": "Continue with GitHub",
    "orContinueWith": "Or continue with",
    "failed": "Couldn't start that sign-in. Please try again or use your email."
  },
  "validation": {
    "emailInvalid": "Please enter a valid email address",
    "passwordTooShort": "Password must be at least 8 characters"
  }
}

"use client";

/**
 * Error boundary for the auth route group, which renders outside the
 * app shell. Renders the shared `RouteError` from the `route-error`
 * item — install it alongside this one.
 */

import { RouteError } from "@/components/shared/route-error";

export default function SegmentError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  return (
    <RouteError
      error={error}
      reset={reset}
      scope="auth"
      fullScreen
      homeHref="/login"
      homeKey="goToLogin"
    />
  );
}
